  for (let i = 0; i < subAreaDefs.length; i += 100) {
    const chunk = subAreaDefs.slice(i, i + 100);
    await Promise.all(chunk.map(async ([areaNorm, subNorm, areaDisp, subDisp]) => {
      const areaId = areaMap[areaDisp.toLowerCase().trim()];
      if (!areaId) return;
      const isCovered = coveredSet.has(subDisp);
      const r = await prisma.subArea.upsert({
        where: { areaId_name: { areaId, name: subDisp } },
        update: {},
        create: { areaId, name: subDisp, isCovered, pickupPolicy: "ROUTE_BASED" },
      });
      subAreaMap[`${areaNorm}|${subNorm}`] = r.id;
    }));
    if ((i % 500) === 0 && i > 0) process.stdout.write(".");
  }
  console.log();

