    await Promise.all(chunk.map(async ([an, sn, bn, bd]) => {
      const subAreaId = subAreaMap[`${an}|${sn}`];
      if (!subAreaId) return;
      const r = await prisma.block.upsert({
        where: { subAreaId_name: { subAreaId, name: bd } },
        update: {},
        create: { subAreaId, name: bd },
      });
      blockMap[`${an}|${sn}|${bn}`] = r.id;
    }));
    if ((i % 500) === 0 && i > 0) process.stdout.write(".");
