  const mkLabel = (m) => {
    if (m === null || m === undefined) return "";
    const h = Math.floor(m / 60); const mn = m % 60;
    const ap = h >= 12 ? "PM" : "AM"; const h12 = h % 12 || 12;
    return `${h12}${mn ? ":"+String(mn).padStart(2,"0") : ""}${ap}`;
  };
  await Promise.all(routeDefs.map(async ([code, driverStr, shift, vendor, pickupMin, dropMin, dk1, dk2]) => {
    const primaryDriverId = dk1 ? (driverKeyMap[dk1] ?? null) : null;
    const secondaryDriverId = dk2 ? (driverKeyMap[dk2] ?? null) : null;
    const shiftLabel = (pickupMin != null && dropMin != null) ? `${mkLabel(pickupMin)}-${mkLabel(dropMin)}` : shift;
    const r = await prisma.route.upsert({
      where: { code },
      update: {
        ...(primaryDriverId ? { primaryDriverId } : {}),
        ...(secondaryDriverId ? { secondaryDriverId } : {}),
      },
      create: {
        code, name: `${driverStr} | ${shift}`,
        cityId: city.id,
        startPoint: "Karachi Pickup Zone",
        endPoint: "Office",
        ...(primaryDriverId ? { primaryDriverId } : {}),
        ...(secondaryDriverId ? { secondaryDriverId } : {}),
      },
    });
    if (primaryDriverId) {
      await prisma.driver.update({ where: { id: primaryDriverId }, data: { defaultRouteId: r.id } }).catch(() => {});
    }
    routeCodeMap[code] = r.id;
  }));

